938: function applyEdits(world, edits) {
939:   if (!edits) return;
940:   let count = 0;
941:   for (const [key, block] of Object.entries(edits)) {
942:     const [x, y, z] = key.split(',').map(Number);
943:     if (![x, y, z, block].every(Number.isFinite)) continue;
944:     if (world.setBlock(x, y, z, block)) count++;
945:     if (count > 12000) break;
946:   }
947: }
