956: async function enterGame(meta) {
957:   if (entering) return;
958:   entering = true;
959:   state.loading = true;
960:   closeModal();
961:   hud.hidden = true;
962:   hud.classList.remove('dimmed');
963:   showScreen('loading');
964:   const tipEl = $('#loading-tip-text');
965:   if (tipEl) tipEl.textContent = pickTip();
966:   setLoadingProgress(0.02, tUI(meta.serverName ? 'loading.connecting' : 'loading.generating'), tUI('loading.sub'));
967: 
968:   try {
969:     await nextFrame();
970:     if (meta.serverName) await delay(620);
971:     setLoadingProgress(0.08, tUI(meta.serverName ? 'loading.joining' : 'loading.generating'), tUI('loading.sub'));
972: 
973:     const world = new VoxelWorld({ size: 112, height: 48, seed: meta.seed || randomSeed() });
974:     world.generate();
975:     applyEdits(world, meta.edits);
976: 
977:     setLoadingProgress(0.16, tUI('loading.building'), tUI('loading.sub'));
978:     await world.buildAllAsync(p => {
979:       setLoadingProgress(0.16 + p * 0.76, p > 0.55 ? tUI('loading.building') : tUI('loading.generating'), null);
980:     });
981: 
982:     setLoadingProgress(1, tUI('loading.preparing'), tUI('loading.sub'));
983:     await nextFrame();
984:     await delay(120);
985: 
986:     if (!viewer || !canvas) throw new Error('Renderer unavailable');
987:     game = new Game({
988:       viewer,
989:       world,
990:       app: makeAppApi(),
991:       options: state.options,
992:       worldMeta: meta,
993:       t: tUI
994:     });
995: 
996:     state.inGame = true;
997:     state.loading = false;
998:     state.currentWorldMeta = meta;
999:     if (meta.id) {
1000:       const stored = state.worlds.find(w => w.id === meta.id);
1001:       if (stored) stored.lastPlayed = Date.now();
1002:       saveWorlds();
1003:     }
1004:     showScreen(null);
1005:     hud.classList.remove('dimmed');
1006:     state.paused = !game.isTouch && game.paused;
1007: 
1008:     setTimeout(() => {
1009:       if (!game) return;
1010:       if (meta.serverName) toast(tUI('toast.connected', { s: meta.serverName }), 'plain');
1011:       else toast(tUI('game.welcome', { s: meta.name }), 'plain');
1012:     }, 500);
1013:   } catch (err) {
1014:     console.error(err);
1015:     state.loading = false;
1016:     state.inGame = false;
1017:     game = null;
1018:     hud.hidden = true;
1019:     showScreen('mainmenu');
1020:     toast(state.lang === 'pt' ? 'Erro ao carregar o mundo.' : 'Failed to load the world.', 'error');
1021:   } finally {
1022:     entering = false;
1023:   }
1024: }
