1038: /* ============================================================
1039:    Toasts
1040:    ============================================================ */
1041: function toast(text, kind = 'plain') {
1042:   const stack = $('#toasts');
1043:   if (!stack) return;
1044:   while (stack.children.length >= 3) stack.firstElementChild.remove();
1045:   const el = document.createElement('div');
1046:   el.className = 'toast ' + kind;
1047:   const body = document.createElement('div');
1048:   body.className = 'toast-body';
1049:   const desc = document.createElement('div');
1050:   desc.className = 'toast-desc';
1051:   desc.textContent = text;
1052:   body.appendChild(desc);
1053:   el.appendChild(body);
1054:   stack.appendChild(el);
1055:   setTimeout(() => {
1056:     el.classList.add('out');
1057:     setTimeout(() => el.remove(), 450);
1058:   }, kind === 'error' ? 3200 : 2600);
1059: }
