295: function buildAtlasCanvas() {
296:   const atlas = document.createElement('canvas');
297:   atlas.width = ATLAS_SIZE; atlas.height = ATLAS_SIZE;
298:   const g = atlas.getContext('2d');
299:   g.imageSmoothingEnabled = false;
300:   const list = tiles();
301:   for (let i = 0; i < list.length; i++) {
302:     const col = i % ATLAS_COLS, row = (i / ATLAS_COLS) | 0;
303:     const cx = col * CELL, cy = row * CELL;
304:     const ox = cx + (CELL - ART) / 2, oy = cy + (CELL - ART) / 2;
305:     g.clearRect(cx, cy, CELL, CELL);
306:     // edge bleed padding (helps mipmaps / filtering)
307:     g.drawImage(list[i], 0, 0, ART, 1, ox, oy - 8, ART, 8);
308:     g.drawImage(list[i], 0, ART - 1, ART, 1, ox, oy + ART, ART, 8);
309:     g.drawImage(list[i], 0, 0, 1, ART, ox - 8, oy, 8, ART);
310:     g.drawImage(list[i], ART - 1, 0, 1, ART, ox + ART, oy, 8, ART);
311:     g.fillStyle = '#000';
312:     g.imageSmoothingEnabled = false;
313:     g.drawImage(list[i], ox, oy);
314:     // corners
315:     g.drawImage(list[i], 0, 0, 1, 1, ox - 8, oy - 8, 8, 8);
316:     g.drawImage(list[i], ART - 1, 0, 1, 1, ox + ART, oy - 8, 8, 8);
317:     g.drawImage(list[i], 0, ART - 1, 1, 1, ox - 8, oy + ART, 8, 8);
318:     g.drawImage(list[i], ART - 1, ART - 1, 1, 1, ox + ART, oy + ART, 8, 8);
319:   }
320:   return atlas;
321: }
