490: export class VoxelWorld {
491:   constructor({ size = 112, height = 48, seed = 'playground' } = {}) {
492:     this.size = size;
493:     this.height = height;
494:     this.seedString = String(seed);
495:     this.seed = hashString(this.seedString);
496:     this.blocks = new Uint8Array(size * size * height);
497:     this.group = new THREE.Group();
498:     this.group.name = 'voxel-world';
499:     this.chunkData = new Map();
500:     this.materials = {
501:       opaque: new THREE.MeshBasicMaterial({ map: atlasTexture(), vertexColors: true }),
502:       water: new THREE.MeshBasicMaterial({
503:         map: atlasTexture(), vertexColors: true, transparent: true,
504:         opacity: 0.78, depthWrite: false, side: THREE.FrontSide
505:       }),
506:       plants: new THREE.MeshBasicMaterial({
507:         map: atlasTexture(), vertexColors: true, alphaTest: 0.35,
508:         side: THREE.DoubleSide
509:       })
510:     };
511:     this.trees = [];
512:   }
513: 
514:   index(x, y, z) { return (y * this.size + z) * this.size + x; }
515: 
516:   getBlock(x, y, z) {
517:     if (y < 0) return BLOCKS.BEDROCK;
518:     if (y >= this.height) return BLOCKS.AIR;
519:     if (x < 0 || z < 0 || x >= this.size || z >= this.size) return BLOCKS.AIR;
520:     return this.blocks[(y * this.size + z) * this.size + x];
521:   }
522: 
523:   setBlock(x, y, z, b) {
524:     if (x < 0 || z < 0 || y < 0 || x >= this.size || z >= this.size || y >= this.height) return false;
525:     this.blocks[(y * this.size + z) * this.size + x] = b;
526:     return true;
527:   }
528: 
529:   surfaceY(x, z) {
530:     const xi = Math.floor(x), zi = Math.floor(z);
531:     if (xi < 0 || zi < 0 || xi >= this.size || zi >= this.size) return 0;
532:     for (let y = this.height - 1; y >= 0; y--) {
533:       const b = this.getBlock(xi, y, zi);
534:       if (IS_SOLID(b) && !IS_PLANT(b)) return y;
535:     }
536:     return 0;
537:   }
538: 
539:   generate() {
540:     const S = this.size, H = this.height;
541:     const mountainX = S * 0.30, mountainZ = S * 0.30;
542:     const lakeX = S * 0.70, lakeZ = S * 0.56;
543:     const heights = new Int16Array(S * S);
544: 
545:     for (let z = 0; z < S; z++) {
546:       for (let x = 0; x < S; x++) {
547:         const n1 = noise2(x * 0.028, z * 0.028, this.seed);
548:         const n2 = noise2(x * 0.075, z * 0.075, this.seed + 17);
549:         const n3 = noise2(x * 0.19, z * 0.19, this.seed + 39);
550:         let h = 7.0 + n1 * 8.5 + n2 * 3.6 + n3 * 1.3;
551: 
552:         const mdx = (x - mountainX) / (S * 0.21), mdz = (z - mountainZ) / (S * 0.24);
553:         h += 15 * Math.exp(-(mdx * mdx + mdz * mdz) * 1.35);
554:         const ldx = (x - lakeX) / (S * 0.19), ldz = (z - lakeZ) / (S * 0.17);
555:         h -= 7.4 * Math.exp(-(ldx * ldx + ldz * ldz) * 1.7);
556: 
557:         const edge = Math.min(x, z, S - 1 - x, S - 1 - z);
558:         if (edge < 18) h -= (18 - edge) * 0.95;
559:         h = Math.max(2, Math.min(H - 8, Math.round(h)));
560:         heights[z * S + x] = h;
561:       }
562:     }
563: 
564:     // base terrain
565:     for (let z = 0; z < S; z++) {
566:       for (let x = 0; x < S; x++) {
567:         const h = heights[z * S + x];
568:         for (let y = 0; y <= h; y++) {
