```js
const iconCache = new Map();
function storeIconURL(item) {
  if (iconCache.has(item.id)) return iconCache.get(item.id);
  const c=document.createElement('canvas'); c.width=64;c.height=64;
  const g=c.getContext('2d');
  const hue=item.hue||200;
  const grd=g.createLinearGradient(0,0,64,64);
  grd.addColorStop(0,`hsl(${hue},48%,40%)`); grd.addColorStop(1,`hsl(${hue+26},46%,15%)`);
  g.fillStyle=grd; g.fillRect(0,0,64,64);
  // pixel grid
  g.fillStyle='rgba(0,0,0,.18)';
  for(let y=0;y<64;y+=8)g.fillRect(0,y,64,1);
  for(let x=0;x<64;x+=8)g.fillRect(x,0,1,64);
  if (item.kind === 'map') {
    // diamond terrain
    g.save(); g.translate(32,30); g.rotate(Math.PI/4);
    g.fillStyle=`hsl(${hue},55%,58%)`; g.fillRect(-16,-16,32,32);
    g.fillStyle='rgba(255,255,255,.25)'; g.fillRect(-16,-16,32,8);
    g.fillStyle='rgba(0,0,0,.25)'; g.fillRect(-16,8,32,8);
    g.restore();
    g.fillStyle='#e8e8e8'; g.fillRect(28,44,8,12);
    g.fillStyle='#b33'; g.fillRect(35,42,8,8);
  } else {
    // gear-ish
    g.fillStyle='#e6e6e6'; g.fillRect(26,18,12,28); g.fillRect(18,26,28,12);
    g.fillStyle=`hsl(${hue},60%,45%)`; g.fillRect(28,28,8,8);
    g.fillStyle='rgba(0,0,0,.35)'; g.fillRect(18,42,28,4);
  }
  g.fillStyle='rgba(0,0,0,.35)'; g.fillRect(0,58,64,6);
  const url=c.toDataURL('image/png');
  iconCache.set(item.id,url);
  return url;
}
