```js
function pixelTexture(canvas) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  tex.generateMipmaps = false;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeSkinCanvas() {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 64;
  const g = c.getContext('2d');
  const palette = ['#5f9440', '#568a39', '#6aa14a', '#4d7a33', '#719f52', '#436b2c'];
  for (let y = 0; y < 64; y += 4) for (let x = 0; x < 64; x += 4) {
    g.fillStyle = palette[(Math.random()*palette.length)|0];
    g.fillRect(x, y, 4, 4);
  }
  // torn rot patches
  for (let i=0;i<9;i++){
    const x=(Math.random()*56)|0, y=(Math.random()*56)|0;
    g.fillStyle='rgba(30,50,18,.75)';
    g.fillRect(x,y,4,4);
  }
  // dark seam / stitches
  g.fillStyle='rgba(20,35,12,.55)';
  g.fillRect(0, 44, 64, 3);
  g.fillStyle='#c9d6b0';
  for (let x=4;x<64;x+=12) g.fillRect(x, 43, 5, 2);
  return c;
}
