```js
updateHand(dt) {
  if (!this.armGroup) return;
  this.handTime = (this.handTime || 0) + dt;
  const p = this.player;
  const speed = Math.hypot(p.vel.x, p.vel.z);
  const walk = p.onGround && !p.fly ? Math.min(1, speed / 4.15) : 0;
  this.swingPhase = Math.min(1, (this.swingPhase ?? 1) + dt * 3.6);
  const s = this.swingPhase < 1 ? Math.sin(this.swingPhase * Math.PI) : 0;
  const t = this.handTime;
  const idle = Math.sin(t * 1.6) * 0.006;
  const bobX = Math.sin(p.bob * 2.4) * 0.014 * walk;
  const bobY = Math.abs(Math.cos(p.bob * 2.4)) * 0.016 * walk;
  const b = this.handBase;
  this.armGroup.position.set(
    b.x + bobX - s * 0.05, b.y - bobY + idle + s * 0.02, b.z + s * 0.16
  );
