buildHand() {
  const zombie = this.mods.zombieArm !== false;
  this.viewer.scene.add(this.viewer.camera);

  this.armGroup = new THREE.Group();
  this.handMaterials = [];
  const skinMat = new THREE.MeshBasicMaterial({ map: pixelTexture(armCanvas(zombie)), fog: false });
  const sleeveMat = new THREE.MeshBasicMaterial({ map: pixelTexture(sleeveCanvas(zombie)), fog: false });
  this.handMaterials.push(skinMat, sleeveMat);

  const armMesh = new THREE.Mesh(new THREE.BoxGeometry(0.21, 0.21, 0.56), skinMat);
  armMesh.position.set(0, 0, -0.28);

  const sleeve = new THREE.Mesh(new THREE.BoxGeometry(0.248, 0.248, 0.2), sleeveMat);
  sleeve.position.set(0, 0, -0.1);

  const hand = new THREE.Mesh(new THREE.BoxGeometry(0.226, 0.226, 0.15), skinMat);
  hand.position.set(0, 0, -0.53);

  const thumb = new THREE.Mesh(new THREE.BoxGeometry(0.075, 0.1, 0.14), skinMat);
  thumb.position.set(-0.13, 0.03, -0.5);
  thumb.rotation.set(0.1, 0, -0.18);

  this.handBlockMat = new THREE.MeshBasicMaterial({
    map: pixelTexture(blockCanvas(this.hotbar[this.selected].tile)),
    fog: false
  });
  this.handMaterials.push(this.handBlockMat);
  this.handBlock = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.22, 0.22), this.handBlockMat);
  this.handBlock.position.set(0.01, 0.11, -0.56);
  this.handBlock.rotation.set(0.26, 0.68, 0.12);

  for (const mesh of [armMesh, sleeve, hand, thumb, this.handBlock]) {
    mesh.renderOrder = 30;
    mesh.frustumCulled = false;
    this.armGroup.add(mesh);
  }

  const b = this.handBase;
  this.armGroup.position.set(b.x, b.y, b.z);
  this.armGroup.rotation.set(b.rx, b.ry, b.rz);
  this.viewer.camera.add(this.armGroup);
}

swingHand() {
  this.swingPhase = 0;
}

updateHand(dt) {
  if (!this.armGroup) return;
  this.handTime += dt;
  const p = this.player;
  const hspeed = Math.hypot(p.vel.x, p.vel.z);
  const walk = p.onGround && !p.fly ? clamp(hspeed / 4.15, 0, 1) : 0;
  this.swingPhase = Math.min(1, this.swingPhase + dt * 3.8);
  const s = this.swingPhase < 1 ? Math.sin(this.swingPhase * Math.PI) : 0;
  const idle = Math.sin(this.handTime * 1.7) * 0.006;
  const bobX = Math.sin(p.bob * 2.4) * 0.014 * walk;
  const bobY = Math.abs(Math.cos(p.bob * 2.4)) * 0.016 * walk;
  const b = this.handBase;
  this.armGroup.position.set(
    b.x + bobX - s * 0.05,
    b.y - bobY + idle + s * 0.02,
    b.z + s * 0.16
  );
  this.armGroup.rotation.set(b.rx - s * 0.72, b.ry + s * 0.16, b.rz + s * 0.22);
}

updateHandBlock() {
  if (!this.handBlockMat) return;
  const tex = pixelTexture(blockCanvas(this.hotbar[this.selected].tile));
  const old = this.handBlockMat.map;
  this.handBlockMat.map = tex;
  this.handBlockMat.needsUpdate = true;
  if (old) old.dispose();
}

