390:         this.dom.debug.hidden = !this.debug;
391:         this.dom.fpsNote.style.display = this.debug ? 'none' : '';
392:         return;
393:       }
394:       if (e.code === 'Space' && !e.repeat) {
395:         const now = performance.now();
396:         if (this.creative && now - this.player.lastSpace < 300) {
397:           this.player.fly = !this.player.fly;
398:           this.player.vel.y = 0;
399:           if (this.player.fly && !this.stats.firstFly) {
