540:   moveJoystick(e) {
541:     const rect = this.dom.joystick.getBoundingClientRect();
542:     const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
543:     let dx = e.clientX - cx, dy = e.clientY - cy;
544:     const max = rect.width * 0.32;
545:     const len = Math.hypot(dx, dy);
546:     if (len > max) { dx = dx / len * max; dy = dy / len * max; }
547:     this.dom.knob.style.transform = `translate(${dx}px, ${dy}px)`;
548:     this.joystick.x = dx / max;
549:     this.joystick.y = dy / max;
550:   }
