590:   /* ---------------- physics & camera ---------------- */
591:   collides(x = this.player.pos.x, y = this.player.pos.y, z = this.player.pos.z) {
592:     const half = 0.3;
593:     const minX = Math.floor(x - half + 0.0001);
594:     const maxX = Math.floor(x + half - 0.0001);
595:     const minY = Math.floor(y + 0.0001);
596:     const maxY = Math.floor(y + 1.79);
597:     const minZ = Math.floor(z - half + 0.0001);
598:     const maxZ = Math.floor(z + half - 0.0001);
599:     for (let by = minY; by <= maxY; by++) {
600:       for (let bz = minZ; bz <= maxZ; bz++) {
601:         for (let bx = minX; bx <= maxX; bx++) {
602:           if (IS_SOLID(this.world.getBlock(bx, by, bz))) return true;
603:         }
604:       }
605:     }
606:     return false;
607:   }
608: 
609:   updatePlayer(dt) {
610:     const p = this.player;
611:     const keys = this.keys;
612:     const waterBlock = this.world.getBlock(Math.floor(p.pos.x), Math.floor(p.pos.y + 0.9), Math.floor(p.pos.z));
613:     p.inWater = waterBlock === BLOCKS.WATER;
614: 
615:     let ix = 0, iz = 0;
616:     if (this.isTouch) {
617:       ix = this.joystick.x;
618:       iz = -this.joystick.y;
619:     } else {
620:       if (keys.has('KeyW') || keys.has('ArrowUp')) iz += 1;
621:       if (keys.has('KeyS') || keys.has('ArrowDown')) iz -= 1;
622:       if (keys.has('KeyD') || keys.has('ArrowRight')) ix += 1;
623:       if (keys.has('KeyA') || keys.has('ArrowLeft')) ix -= 1;
624:     }
625:     if (Math.hypot(ix, iz) > 1) { const l = Math.hypot(ix, iz); ix /= l; iz /= l; }
626: 
627:     const sprinting = !p.fly && (keys.has('ShiftLeft') || keys.has('ShiftRight')) && iz > 0;
628:     const speedBoost = this.mods.rabbitBoots ? 1.4 : 1;
629:     const speed = (p.fly ? 10.5 : p.inWater ? 3.2 : sprinting ? 5.9 : 4.15) * speedBoost;
630:     const sin = Math.sin(p.yaw), cos = Math.cos(p.yaw);
631:     const dirX = -sin * iz + cos * ix;
632:     const dirZ = -cos * iz - sin * ix;
633:     const targetX = dirX * speed, targetZ = dirZ * speed;
634:     const accel = p.fly ? 12 : p.onGround ? 16 : p.inWater ? 6 : 4.5;
635:     const k = Math.min(1, accel * dt);
636:     p.vel.x += (targetX - p.vel.x) * k;
637:     p.vel.z += (targetZ - p.vel.z) * k;
638: 
639:     const jump = this.jumpHeld || (this.isTouch ? false : keys.has('Space'));
640:     if (p.fly) {
641:       let vy = 0;
642:       if (jump) vy += 7.5;
643:       if (keys.has('ShiftLeft') || keys.has('ShiftRight')) vy -= 7.5;
644:       p.vel.y += (vy - p.vel.y) * Math.min(1, 12 * dt);
645:     } else if (p.inWater) {
646:       p.vel.y -= 7 * dt;
647:       if (jump) p.vel.y = 4.0;
648:       p.vel.y = Math.max(p.vel.y, -3.0);
649:       p.vel.x *= 0.995;
650:       p.vel.z *= 0.995;
651:     } else {
652:       p.vel.y -= 28 * dt;
653:       if (jump && p.onGround) { p.vel.y = 8.4 * (this.mods.slimeJump ? 1.3 : 1); p.onGround = false; }
654:       if (p.vel.y < -40) p.vel.y = -40;
655:     }
656: 
657:     // integrate with small collision steps
658:     const maxSpeed = p.fly ? 12 : 10;
659:     p.vel.x = clamp(p.vel.x, -maxSpeed, maxSpeed);
660:     p.vel.z = clamp(p.vel.z, -maxSpeed, maxSpeed);
661:     const dx = p.vel.x * dt, dy = p.vel.y * dt, dz = p.vel.z * dt;
662:     const steps = Math.max(1, Math.ceil(Math.max(Math.abs(dx), Math.abs(dy), Math.abs(dz)) / 0.1));
663:     const sdt = dt / steps;
664:     let hitY = false;
665:     for (let i = 0; i < steps; i++) {
666:       p.pos.x += p.vel.x * sdt;
667:       if (this.collides()) { p.pos.x -= p.vel.x * sdt; p.vel.x = 0; }
668:       p.pos.z += p.vel.z * sdt;
669:       if (this.collides()) { p.pos.z -= p.vel.z * sdt; p.vel.z = 0; }
670:       p.pos.y += p.vel.y * sdt;
671:       if (this.collides()) {
672:         p.pos.y -= p.vel.y * sdt;
673:         if (p.vel.y < 0) { p.onGround = true; hitY = true; }
674:         p.vel.y = 0;
675:       }
676:     }
677: 
678:     const limit = this.world.size - 1.2;
679:     p.pos.x = clamp(p.pos.x, 1.2, limit);
680:     p.pos.z = clamp(p.pos.z, 1.2, limit);
681:     if (p.pos.y < -8) {
682:       p.pos.set(this.world.spawn.x, this.world.spawn.y + 2, this.world.spawn.z);
683:       p.vel.set(0, 0, 0);
684:     }
685: 
686:     if (!hitY) {
687:       p.onGround = this.collides(p.pos.x, p.pos.y - 0.06, p.pos.z);
688:     }
689:     if (p.fly && p.onGround) {
690:       // keep flying, but hover just above ground
691:       if (p.vel.y < 0) p.vel.y = 0;
692:     }
693: 
694:     // footsteps + bob
695:     const hspeed = Math.hypot(p.vel.x, p.vel.z);
696:     if (p.onGround && hspeed > 1.2 && !p.fly) {
697:       p.stepAccum += hspeed * dt;
698:       p.bob += hspeed * dt;
699:       if (p.stepAccum > 2.1) { p.stepAccum = 0; this.app.audio?.step(); }
700:     } else {
701:       p.bob *= Math.pow(0.001, dt);
702:       p.stepAccum = Math.min(p.stepAccum, 1.6);
703:     }
704: 
705:     this.sprinting = sprinting;
706:   }
707: 
708:   eyeHeight() { return 1.62; }
709: 
710:   updateCamera(dt) {
711:     const p = this.player;
712:     const moving = p.onGround && Math.hypot(p.vel.x, p.vel.z) > 0.8 && !p.fly;
713:     const bob = moving ? Math.sin(p.bob * 2.4) * 0.035 : 0;
714:     this.viewer.camera.position.set(p.pos.x, p.pos.y + this.eyeHeight() + bob, p.pos.z);
715:     this.viewer.camera.rotation.set(p.pitch, p.yaw, 0, 'YXZ');
716: 
717:     const targetFov = this.options.fov + (this.sprinting && moving ? 5 : 0) + (p.fly ? 2 : 0);
718:     if (Math.abs(targetFov - this.currentFov) > 0.02) {
719:       this.currentFov += (targetFov - this.currentFov) * Math.min(1, dt * 8);
720:       this.viewer.camera.fov = this.currentFov;
721:       this.viewer.camera.updateProjectionMatrix();
722:     }
723: 
724:     const eyeBlock = this.world.getBlock(
725:       Math.floor(p.pos.x), Math.floor(p.pos.y + this.eyeHeight()), Math.floor(p.pos.z)
726:     );
727:     const underwater = eyeBlock === BLOCKS.WATER;
728:     if (underwater !== this.underwater) {
729:       this.underwater = underwater;
730:       document.body.classList.toggle('underwater', underwater);
731:       const fog = this.viewer.scene.fog;
732:       if (underwater) {
733:         this._fogColor = fog.color.getHex();
734:         this._fogNear = fog.near;
735:         this._fogFar = fog.far;
736:         fog.color.setHex(0x2c6fa8);
737:         fog.near = 0.5;
738:         fog.far = 22;
739:         this.viewer.renderer.setClearColor(0x2c6fa8, 1);
740:       } else {
741:         fog.color.setHex(this._fogColor ?? 0xc9dfef);
742:         fog.near = this._fogNear ?? 55;
743:         fog.far = this._fogFar ?? 150;
744:         this.viewer.renderer.setClearColor(0x9cc7e6, 1);
745:       }
746:     }
747:   }
748: 
749:   update(dt) {
750:     if (this.destroyed) return;
751:     this.fpsAccum += dt;
752:     this.fpsFrames++;
753:     if (this.fpsAccum > 0.5) {
754:       this.fps = Math.round(this.fpsFrames / this.fpsAccum);
755:       this.fpsAccum = 0;
756:       this.fpsFrames = 0;
757:     }
758: 
759:     if (!this.paused) {
760:       if (this.isTouch || this.locked) {
761:         this.updatePlayer(dt);
762:         this.updateHighlight();
763:         this.updateParticles(dt);
764:       }
765:     }
766:     this.updateCamera(dt);
767:     this.updateHand(dt);
768:     if (!this.paused && (this.isTouch || this.locked)) {
769:       if (this.debug) this.updateDebug();
770:       if (this.isTouch) this.dom.fpsNote.textContent = '';
771:     }
772:   }
