774:   updateHighlight() {
775:     const hit = this.raycast(this.reach);
776:     if (hit) {
777:       this.highlight.visible = true;
778:       this.highlight.position.set(hit.x + 0.5, hit.y + 0.5, hit.z + 0.5);
779:     } else {
780:       this.highlight.visible = false;
781:     }
782:   }
