784:   updateDebug() {
785:     const p = this.player;
786:     const dirs = ['sul', 'sudoeste', 'oeste', 'noroeste', 'norte', 'nordeste', 'leste', 'sudeste'];
787:     const index = Math.round((((p.yaw * 180 / Math.PI) % 360) + 360) % 360 / 45) % 8;
788:     const dirNames = this.lang === 'pt' ? dirs : ['south', 'southwest', 'west', 'northwest', 'north', 'northeast', 'east', 'southeast'];
789:     const item = this.hotbar[this.selected];
790:     this.dom.debug.textContent =
791:       `${this.t('debug.fps')}: ${this.fps}\n` +
792:       `${this.t('debug.xyz')}: ${p.pos.x.toFixed(1)} / ${p.pos.y.toFixed(1)} / ${p.pos.z.toFixed(1)}\n` +
793:       `${this.t('debug.chunk')}: ${Math.floor(p.pos.x / 16)}, ${Math.floor(p.pos.z / 16)}\n` +
794:       `${this.t('debug.facing')}: ${dirNames[index]}\n` +
795:       `${this.t('debug.mode')}: ${this.creative ? this.t('mode.creative') : this.t('mode.survival')}${p.fly ? ' • ✈' : ''}\n` +
796:       `${this.t('debug.block')}: ${this.t(item.name)}\n` +
797:       `${this.t('debug.hint')}`;
798:   }
