800:   updateParticles(dt) {
801:     for (let i = this.particles.length - 1; i >= 0; i--) {
802:       const pt = this.particles[i];
803:       pt.life -= dt;
804:       if (pt.life <= 0) {
805:         this.particleGroup.remove(pt.mesh);
806:         this.particles.splice(i, 1);
807:         continue;
808:       }
809:       pt.vel.y -= 24 * dt;
810:       pt.mesh.position.addScaledVector(pt.vel, dt);
811:       pt.mesh.rotation.x += dt * 5;
812:       pt.mesh.rotation.y += dt * 4;
813:       const s = Math.max(0.02, pt.life / pt.maxLife);
814:       pt.mesh.scale.setScalar(s);
815:       if (pt.mesh.position.y < 0) pt.life = 0;
816:     }
817:   }
818: 
819:   /* ---------------- interaction ---------------- */
820:   raycast(maxDist = 6) {
821:     const p = this.player;
822:     const origin = new THREE.Vector3(p.pos.x, p.pos.y + this.eyeHeight(), p.pos.z);
823:     const dir = new THREE.Vector3(0, 0, -1);
824:     dir.applyEuler(new THREE.Euler(p.pitch, p.yaw, 0, 'YXZ'));
825: 
826:     let x = Math.floor(origin.x), y = Math.floor(origin.y), z = Math.floor(origin.z);
827:     const stepX = dir.x > 0 ? 1 : -1;
828:     const stepY = dir.y > 0 ? 1 : -1;
829:     const stepZ = dir.z > 0 ? 1 : -1;
830:     const tDeltaX = dir.x === 0 ? Infinity : Math.abs(1 / dir.x);
831:     const tDeltaY = dir.y === 0 ? Infinity : Math.abs(1 / dir.y);
832:     const tDeltaZ = dir.z === 0 ? Infinity : Math.abs(1 / dir.z);
833:     let tMaxX = dir.x === 0 ? Infinity : (stepX > 0 ? (x + 1 - origin.x) : (origin.x - x)) * tDeltaX;
834:     let tMaxY = dir.y === 0 ? Infinity : (stepY > 0 ? (y + 1 - origin.y) : (origin.y - y)) * tDeltaY;
835:     let tMaxZ = dir.z === 0 ? Infinity : (stepZ > 0 ? (z + 1 - origin.z) : (origin.z - z)) * tDeltaZ;
836:     let normal = [0, 0, 0];
837:     let t = 0;
838: 
