770: function storeIconURL(item) {
771:   if (storeIconCache.has(item.id)) return storeIconCache.get(item.id);
772:   const c = document.createElement('canvas');
773:   c.width = 64; c.height = 64;
774:   const g = c.getContext('2d');
775:   const hue = item.hue ?? 200;
776:   const grd = g.createLinearGradient(0, 0, 64, 64);
777:   grd.addColorStop(0, `hsl(${hue}, 48%, 42%)`);
778:   grd.addColorStop(1, `hsl(${hue + 26}, 46%, 15%)`);
779:   g.fillStyle = grd;
780:   g.fillRect(0, 0, 64, 64);
781:   g.fillStyle = 'rgba(0,0,0,.2)';
782:   for (let y = 0; y < 64; y += 8) g.fillRect(0, y, 64, 1);
783:   for (let x = 0; x < 64; x += 8) g.fillRect(x, 0, 1, 64);
784: 
785:   if (item.kind === 'map') {
786:     g.fillStyle = 'rgba(0,0,0,.35)';
787:     g.fillRect(14, 16, 38, 36);
788:     g.fillStyle = '#d9c9a3';
789:     g.fillRect(11, 13, 38, 36);
790:     g.fillStyle = `hsl(${hue}, 42%, 44%)`;
791:     g.fillRect(15, 17, 30, 26);
792:     g.fillStyle = 'rgba(160,220,255,.55)';
793:     g.fillRect(15, 27, 30, 3);
794:     g.fillStyle = '#7a4b2a';
795:     for (let i = 0; i < 4; i++) g.fillRect(18 + i * 7, 34 - i * 3, 3, 3);
796:     g.strokeStyle = '#b83a3a';
797:     g.lineWidth = 4;
798:     g.beginPath();
799:     g.moveTo(36, 33); g.lineTo(43, 40);
800:     g.moveTo(43, 33); g.lineTo(36, 40);
801:     g.stroke();
802:     g.strokeStyle = 'rgba(40,30,16,.85)';
803:     g.lineWidth = 2;
804:     g.strokeRect(11, 13, 38, 36);
805:     g.fillStyle = 'rgba(0,0,0,.3)';
806:     g.fillRect(11, 47, 38, 3);
807:   } else {
808:     g.fillStyle = '#ececec';
809:     g.fillRect(26, 17, 12, 30);
810:     g.fillRect(17, 26, 30, 12);
811:     g.fillStyle = `hsl(${hue}, 62%, 46%)`;
812:     g.fillRect(28, 28, 8, 8);
813:     g.fillStyle = 'rgba(0,0,0,.3)';
814:     g.fillRect(17, 43, 30, 4);
815:   }
816: 
817:   g.fillStyle = 'rgba(0,0,0,.35)';
818:   g.fillRect(0, 58, 64, 6);
819:   const url = c.toDataURL('image/png');
820:   storeIconCache.set(item.id, url);
821:   return url;
822: }
