1172:       break;
1173:     case 'language':
1174:       state.languageReturn = game ? 'pause' : state.currentScreen;
1175:       showScreen('language');
1176:       break;
1177:     case 'back-language':
1178:       showScreen(state.languageReturn === 'pause' ? 'pause' : 'mainmenu');
1179:       break;
1180:     case 'accessibility':
1181:       state.accessReturn = game ? 'pause' : state.currentScreen;
