import { characterPalette } from './characters.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

const ZOMBIE_SKIN = ['#7d9a58', '#739050', '#88a562', '#698647', '#93b06e', '#5f7c40'];
const ZOMBIE_SLEEVE = ['#2f5d74', '#2a5368', '#376a83', '#25495c'];
const DEFAULT_SKIN = ['#c69a76', '#bd906c', '#cca27f', '#b98b66', '#d0a883'];
const DEFAULT_SLEEVE = ['#3e6fa8', '#39679c', '#4579b3', '#335d8f'];

function pixelTexture(canvas) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  tex.generateMipmaps = false;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function armCanvas(palette, zombie) {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 64;
  const g = c.getContext('2d');
  for (let y = 0; y < 64; y += 4) {
    for (let x = 0; x < 64; x += 4) {
      g.fillStyle = palette[(Math.random() * palette.length) | 0];
      g.fillRect(x, y, 4, 4);
    }
  }
  if (zombie) {
    for (let i = 0; i < 10; i++) {
      const x = (Math.random() * 56) | 0;
      const y = (Math.random() * 56) | 0;
      g.fillStyle = 'rgba(28,48,16,.72)';
      g.fillRect(x, y, 4, 4);
    }
  }
  g.fillStyle = zombie ? 'rgba(18,32,10,.55)' : 'rgba(90,60,40,.35)';
  g.fillRect(0, 44, 64, 3);
  g.fillStyle = zombie ? '#c7d5ae' : '#e6c8aa';
  for (let x = 4; x < 64; x += 12) g.fillRect(x, 43, 5, 2);
  g.strokeStyle = 'rgba(22,32,14,.72)';
  g.lineWidth = 3;
  g.strokeRect(1.5, 1.5, 61, 61);
  return c;
}

function sleeveCanvas(palette, zombie) {
  const c = document.createElement('canvas');
  c.width = 32; c.height = 32;
  const g = c.getContext('2d');
  for (let y = 0; y < 32; y += 4) {
    for (let x = 0; x < 32; x += 4) {
      g.fillStyle = palette[(Math.random() * palette.length) | 0];
      g.fillRect(x, y, 4, 4);
    }
  }
  if (zombie) {
    g.fillStyle = 'rgba(10,20,26,.8)';
    for (let x = 0; x < 32; x += 8) {
      g.fillRect(x, 26, 4, 6);
      g.fillRect(x + 3, 23, 3, 4);
    }
  }
  g.strokeStyle = 'rgba(10,18,26,.75)';
  g.lineWidth = 2;
  g.strokeRect(1, 1, 30, 30);
  return c;
}

